public class TableRowPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int rows, int cols, int cellSize) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                cols * cellSize, rows * cellSize, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            TableRowPainter.paint(g, rows, cols, cellSize);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(4, 3, 20);
            java.awt.image.BufferedImage b = render(2, 2, 10);
            check("header cell (10,10)", "#404040", pixel(a, 10, 10));
            check("header wins over totals column (50,10)", "#404040", pixel(a, 50, 10));
            check("odd row body cell (10,30)", "#C0C0C0", pixel(a, 10, 30));
            check("totals column on odd row (50,30)", "#FFC800", pixel(a, 50, 30));
            check("even row body cell (30,50)", "#FFFFFF", pixel(a, 30, 50));
            check("totals column on last row (50,70)", "#FFC800", pixel(a, 50, 70));
            check("small grid header (5,5)", "#404040", pixel(b, 5, 5));
            check("small grid totals cell (15,15)", "#FFC800", pixel(b, 15, 15));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

