import java.awt.Color;
import java.awt.Graphics2D;

public class TableRowPainter {

    public static void paint(Graphics2D g, int rows, int cols, int cellSize) {
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                Color fill;
                if (row == 0) {
                    fill = Color.DARK_GRAY;
                } else if (col == cols - 1) {
                    fill = Color.ORANGE;
                } else if (row % 2 == 0) {
                    fill = Color.WHITE;
                } else {
                    fill = Color.LIGHT_GRAY;
                }
                g.setColor(fill);
                g.fillRect(col * cellSize, row * cellSize, cellSize, cellSize);
            }
        }
    }
}
